#include <string.h>

/* lps[i] = length of the longest proper prefix of p[0..i] that is also a suffix */
void build_lps(const char *p, int m, int lps[]) {
  int len = 0;                   /* length of the current matched prefix */
  lps[0] = 0;
  for (int i = 1; i < m; ) {
    if (p[i] == p[len]) {
      lps[i++] = ++len;
    } else if (len > 0) {
      len = lps[len - 1];            /* fall back, do not advance i */
    } else {
      lps[i++] = 0;
    }
  }
}

/* prints every index where p occurs in t; returns the number of matches */
int kmp_search(const char *t, const char *p) {
  int n = strlen(t), m = strlen(p), found = 0;
  if (m == 0) return 0;
  int lps[m];
  build_lps(p, m, lps);
  for (int i = 0, j = 0; i < n; ) {        /* i never moves backward */
    if (t[i] == p[j]) {
      i++; j++;
      if (j == m) {                         /* full match ends at i - 1 */
        printf("match at %d\n", i - m);
        found++;
        j = lps[j - 1];                     /* allow overlapping matches */
      }
    } else if (j > 0) {
      j = lps[j - 1];                       /* reuse the matched prefix */
    } else {
      i++;
    }
  }
  return found;
}

int naive_search(const char *t, const char *p) {
  int n = strlen(t), m = strlen(p), found = 0;
  for (int s = 0; s + m <= n; s++) {          /* every start position */
    int k = 0;
    while (k < m && t[s + k] == p[k]) k++;
    if (k == m) found++;
  }
  return found;       /* worst case O(n * m) */
}

/* z[i] = length of the longest substring starting at i that matches a prefix of s */
void z_function(const char *s, int n, int z[]) {
  z[0] = n;
  for (int i = 1, l = 0, r = 0; i < n; i++) {
    z[i] = 0;
    if (i < r) z[i] = (z[i - l] < r - i) ? z[i - l] : r - i;
    while (i + z[i] < n && s[z[i]] == s[i + z[i]]) z[i]++;
    if (i + z[i] > r) { l = i; r = i + z[i]; }
  }
}

/* smallest period of s: shortest p such that s repeats with period p */
int smallest_period(const char *s, int n, int lps[]) {
  int p = n - lps[n - 1];            /* lps built over s */
  return (n % p == 0) ? p : n;       /* p is a true repeating block only if it divides n */
}
